-- Portable contract fixture. Production uses generated PostgreSQL migrations.
CREATE UNIQUE INDEX uq_tasks_context_project ON tasks(workspace_id,project_id,id);
CREATE TABLE project_context_heads(project_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,sequence INTEGER NOT NULL DEFAULT 0 CHECK(sequence>=0),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE context_documents(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('requirement','decision','constraint')),current_version INTEGER NOT NULL CHECK(current_version BETWEEN 1 AND 500),created_at TEXT NOT NULL,UNIQUE(workspace_id,project_id,id),FOREIGN KEY(workspace_id,project_id) REFERENCES projects(workspace_id,id));
CREATE TABLE context_revisions(document_id TEXT NOT NULL,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 500),title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 200),body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 6000),state TEXT NOT NULL CHECK(state IN ('active','retired')),change_note TEXT NOT NULL CHECK(length(change_note) BETWEEN 1 AND 500),approved_by TEXT NOT NULL REFERENCES users(id),approved_at TEXT NOT NULL,request_id TEXT NOT NULL,input_hash TEXT NOT NULL CHECK(length(input_hash)=64),PRIMARY KEY(document_id,version),UNIQUE(workspace_id,project_id,document_id,version),UNIQUE(workspace_id,project_id,request_id),FOREIGN KEY(workspace_id,project_id,document_id) REFERENCES context_documents(workspace_id,project_id,id));
CREATE TABLE context_events(workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,sequence INTEGER NOT NULL CHECK(sequence>0),document_id TEXT NOT NULL,document_version INTEGER NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(workspace_id,project_id,sequence),FOREIGN KEY(workspace_id,project_id,document_id,document_version) REFERENCES context_revisions(workspace_id,project_id,document_id,version));
CREATE TABLE task_context_briefs(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,task_id TEXT NOT NULL,context_sequence INTEGER NOT NULL CHECK(context_sequence>=0),task_version INTEGER NOT NULL CHECK(task_version>0),fingerprint TEXT NOT NULL CHECK(length(fingerprint)=64),payload TEXT NOT NULL CHECK(length(CAST(payload AS BLOB)) BETWEEN 1 AND 131072),task_hash TEXT NOT NULL CHECK(length(task_hash)=64),created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,request_id TEXT NOT NULL,input_hash TEXT NOT NULL CHECK(length(input_hash)=64),UNIQUE(workspace_id,project_id,task_id,id),UNIQUE(workspace_id,task_id,request_id),FOREIGN KEY(workspace_id,project_id,task_id) REFERENCES tasks(workspace_id,project_id,id));
CREATE INDEX idx_task_context_brief_history ON task_context_briefs(workspace_id,task_id,created_at,id);
CREATE TABLE task_context_bindings(task_id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,project_id TEXT NOT NULL,brief_id TEXT NOT NULL,FOREIGN KEY(workspace_id,project_id,task_id,brief_id) REFERENCES task_context_briefs(workspace_id,project_id,task_id,id));
